        int X, int Y, int Width, int Height,
        int Range,
        int Count, int MinDelaySeconds, int MaxDelaySeconds,
        int? FixedZ,
        Entry[] Entries
    )
    {
        public int Capacity => Math.Min(Count, Entries.Sum(e => e.MaxCount));
    }

