    public static bool IsEodonSpawner(BaseSpawner spawner) =>
        spawner?.Name != null && Definitions.Any(d => string.Equals(d.Name, spawner.Name, StringComparison.Ordinal));

    /// <summary>
    ///     Creates the spawners on Ter Mur, tags them for [DeleteEodon, and fills them, as [GenerateSpawners does
    ///     for ModernUO's own spawn files (ImportSpawnersCommand.cs:168-177).
    /// </summary>
    public static List<Spawner> Generate()
    {
        var list = new List<Spawner>(Definitions.Length);

        foreach (var d in Definitions)
        {
            var bounds = d.FixedZ is { } z
                ? new Rectangle3D(d.X, d.Y, z, Math.Max(1, d.Width), Math.Max(1, d.Height), FixedZBand + 1)
                : new Rectangle3D(d.X, d.Y, Region.MinZ, Math.Max(1, d.Width), Math.Max(1, d.Height), Region.MaxZ - Region.MinZ);

            var spawner = new Spawner(
                d.Count,
                TimeSpan.FromSeconds(d.MinDelaySeconds),
                TimeSpan.FromSeconds(d.MaxDelaySeconds),
                0,
                bounds
            )
            {
                Name = d.Name,
                WalkingRange = d.Range,
                SpawnLocationIsHome = true
            };

            foreach (var entry in d.Entries)
            {
                spawner.AddEntry(entry.Type, entry.MaxCount, entry.MaxCount, false, null, entry.Parameter);
            }

            WeakEntityCollection.Add(EodonGeneration.CollectionKey, spawner);
            spawner.MoveToWorld(new Point3D(d.CentreX, d.CentreY, d.CentreZ), Map.TerMur);
            spawner.Respawn();

            list.Add(spawner);
        }

        return list;
    }
